-- 0104_classic_template_rules.sql (storefront templates, 2026-10-25)
--
-- Tallaby Classic v6: the default template brought up to docs/template-rules.md.
-- Home in the standard order (hero carousel inside the container with rounded
-- corners, categories, best sellers, offers banner + discounted products, new
-- arrivals, trust strip, newsletter), every home section but the hero rises in
-- on scroll, the footer has Shop / Help / Policies columns and a
-- "Powered by Tallaby" link (the storefront then hides its floating badge).
-- Built from packages/store-sections/src/templates/classic/ with
-- `templateConfigJson`. Owner-requested redesign of the default template
-- (CLAUDE.md rule 12), 2026-10-25.
--
-- New stores and "Use template" get it; stores that already have a site are
-- not touched.
--
-- Guarded: only when the template has no admin draft and its current version
-- is still the one 0102 added ('product page') with no later version, so a
-- Classic an admin has edited since is left alone (re-apply by hand then).
-- Idempotent: once applied the current version is no longer 'product page'.

WITH target AS (
  SELECT t.id, cur.version AS cur_version
  FROM templates t
  JOIN template_versions cur ON cur.id = t.current_version_id
  WHERE t.key = 'tallaby-classic' AND t.deleted_at IS NULL AND t.draft_config IS NULL
    AND cur.changelog = 'product page'
    AND NOT EXISTS (SELECT 1 FROM template_versions v WHERE v.template_id = t.id AND v.version > cur.version)
), new_version AS (
  INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
  SELECT target.id, target.cur_version + 1, 1,
